data.query:
query ($orderIds: [String!]!) {
  order(where: { id: { _in: $orderIds } }) {
    edges {
      node {
        id
        number
        loadId
        orderStatusId
        orderLines {
          edges {
            node {
              orderLineReleases {
                edges {
                  node {
                    id
                    quantity { value }
                    orderLineReleaseStatusId
                    pickSteps {
                      edges {
                        node {
                          id
                          pickStepStatusId
                          quantity { value }
                        }
                      }
                    }
                  }
                }
              }
            }
          }
        }
      }
    }
  }
}

data.transform:
{
  "payload": [order.edges.node.(
    $releases := orderLines.edges.node.orderLineReleases.edges.node;
    $allSteps := $releases.pickSteps.edges.node;
    $completedSteps := $allSteps[pickStepStatusId = "picked"];

    $fullyPicked := $count($releases) > 0 and
      $count($releases[$sum(pickSteps.edges.node[pickStepStatusId = "picked"].quantity.value) >= quantity.value]) = $count($releases);

    /* If there is a loadId then it will be picked, packed and shipped */
    $newStatusId := $exists(loadId) and loadId != null ?
      (
        $fullyPicked ? "picked" :
        $count($completedSteps) > 0 ? "partialPick" :
        orderStatusId
      ) :
      (
        $count($releases[$not(orderLineReleaseStatusId = "fulfilled")]) = 0 ? "fulfilled" :
        $count($releases[orderLineReleaseStatusId in ["fulfilled", "partialFulfillment"]]) > 0 ? "partialFulfillment" :
        "pendingFulfillment"
      );

    {
      "where": { "id": id },
      "update": { "orderStatusId": $newStatusId }
    }
  )]
}

